const STORAGE_KEY='k-forum-editor-v1';
const uid=(p='id')=>p+'_'+Date.now().toString(36)+Math.random().toString(36).slice(2,7);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clamp=(n,a,b)=>Math.max(a,Math.min(b,Number(n)||0));
const thumbSvg=(direction='up',className='')=>`<svg class="${className}" viewBox="0 0 24 24" aria-hidden="true"><path d="M7 10v11H3V10h4Zm0 10h10.1a2 2 0 0 0 1.95-1.55l1.4-6A2 2 0 0 0 18.5 10H14l.65-3.25A3 3 0 0 0 11.8 3L7 10Z" ${direction==='down'?'transform="rotate(180 12 12)"':''}/></svg>`;
const talkerBadge=()=>`<div class="hot-badge" aria-label="톡커들의 선택"><svg viewBox="0 0 82 108" aria-hidden="true"><polygon class="badge-star" points="41,2 45,11 55,12 47,19 49,29 41,24 33,29 35,19 27,12 37,11"/><path class="badge-branch" d="M21 70C8 57 8 38 19 24M61 70C74 57 74 38 63 24"/><g class="badge-leaves"><ellipse cx="14" cy="59" rx="4" ry="9" transform="rotate(-35 14 59)"/><ellipse cx="11" cy="45" rx="4" ry="8" transform="rotate(-15 11 45)"/><ellipse cx="16" cy="32" rx="4" ry="8" transform="rotate(18 16 32)"/><ellipse cx="68" cy="59" rx="4" ry="9" transform="rotate(35 68 59)"/><ellipse cx="71" cy="45" rx="4" ry="8" transform="rotate(15 71 45)"/><ellipse cx="66" cy="32" rx="4" ry="8" transform="rotate(-18 66 32)"/></g><g class="badge-thumb"><path d="M36 39v20H27V39h9Zm0 18h17a4 4 0 0 0 3.8-3l2.4-10a4 4 0 0 0-3.9-5H48l1-5a5 5 0 0 0-4.8-6L36 40Z"/></g><rect class="badge-label" x="10" y="69" width="62" height="35" rx="7"/><text x="41" y="84" text-anchor="middle">톡커들의</text><text x="41" y="98" text-anchor="middle">선택!</text></svg></div>`;
const bestBadge=()=>`<span class="best-badge" aria-label="베플">${thumbSvg('up','best-thumb')}<b>베플</b></span>`;
const sample=()=>({id:uid('draft'),name:'雨天便利店 · 示例',createdAt:Date.now(),updatedAt:Date.now(),settings:{scale:2,splitHeight:1160},post:{title:'비 오는 날 편의점에서 자꾸 마주치는 애',titleZh:'总在雨天便利店遇见的那个人',author:'구름빵',time:'2026.10.06 00:47',views:'12,804',likes:184,dislikes:3,hot:true,blocks:[{id:uid('b'),type:'text',original:'요즘 비만 오면 같은 시간에 편의점 가는 사람이 있어\n우산도 늘 투명한 거 쓰고, 꼭 딸기우유 하나만 사감.',translation:'最近每次下雨，都会在同一个时间遇见一个去便利店的人。\n总是撑透明伞，而且只买一瓶草莓牛奶。',overlay:{x:5,y:43,width:90,fontSize:15}},{id:uid('b'),type:'text',original:'어제는 내가 먼저 문 잡아줬는데 작게 감사합니다 하고 웃더라...\n별거 아닌데 집 와서도 계속 생각남 ㅠㅠ',translation:'昨天我先帮他扶住了门，他小声说谢谢，还笑了一下……\n明明没什么，回家以后却一直想起来ㅠㅠ',overlay:{x:3,y:38,width:94,fontSize:15}},{id:uid('b'),type:'text',original:'친구는 그냥 말 걸어보라는데 다음 비 오는 날에도 만날까?',translation:'朋友让我直接搭话。下次下雨还会遇见吗？',overlay:{x:7,y:36,width:86,fontSize:16}}]},comments:[{id:uid('c'),nickname:'ㅇㅇ',time:'2026.10.06 00:52',original:'그 정도면 상대도 시간 맞춰 오는 거 아님? 다음엔 딸기우유 두 개 사ㅋㅋ',translation:'这程度对方也是算好时间来的吧？下次买两瓶草莓牛奶ㅋㅋ',likes:327,dislikes:2,author:false,hot:true,deleted:false,replyTo:'',overlay:{x:1,y:30,width:96,fontSize:14},replies:[{id:uid('r'),nickname:'구름빵',time:'2026.10.06 00:55',original:'아 그 생각은 못했네... 진짜 두 개 사볼까',translation:'啊，我没想到这点……真的要不要买两瓶试试',likes:88,dislikes:0,author:true,hot:false,deleted:false,replyTo:'ㅇㅇ',overlay:{x:2,y:28,width:94,fontSize:14}}]},{id:uid('c'),nickname:'딸기우유',time:'2026.10.06 01:03',original:'투명우산+딸기우유면 너무 청춘드라마잖아 ☔️',translation:'透明伞＋草莓牛奶，这也太青春剧了吧 ☔️',likes:211,dislikes:1,author:false,hot:false,deleted:false,replyTo:'',overlay:{x:2,y:30,width:94,fontSize:14},replies:[]},{id:uid('c'),nickname:'현실주의자',time:'2026.10.06 01:11',original:'비 안 와도 같은 시간에 가봐. 우연인지 아닌지 바로 알 듯',translation:'就算不下雨也在同一时间去看看，很快就知道是不是巧合。',likes:74,dislikes:6,author:false,hot:false,deleted:false,replyTo:'',overlay:{x:2,y:31,width:95,fontSize:14},replies:[]},{id:uid('c'),nickname:'ㅇㅇ',time:'2026.10.06 01:24',original:'삭제된 댓글입니다.',translation:'该评论已删除。',likes:0,dislikes:0,author:false,hot:false,deleted:true,replyTo:'',overlay:{x:2,y:25,width:90,fontSize:14},replies:[]} ]});

let store=loadStore();let currentId=store.currentId;let mode='original';let active={kind:'post'};let editSection='post';let saveTimer;let exportUrls=[];let manualCrop={start:0,height:520,ratio:.75,fullHeight:0,ranges:[],drag:null};
if(!localStorage.getItem('k-forum-overlay-v2')){for(const d of store.drafts){for(const b of d.post.blocks||[])if(b.overlay)b.overlay.y=0;for(const c of d.comments||[]){if(c.overlay)c.overlay.y=0;for(const r of c.replies||[])if(r.overlay)r.overlay.y=0}}localStorage.setItem('k-forum-overlay-v2','1')}
const $=q=>document.querySelector(q);const preview=$('#forumPreview');
function loadStore(){if(window.initialDraftStore?.drafts?.length)return window.initialDraftStore;try{const v=JSON.parse(localStorage.getItem(STORAGE_KEY));if(v?.drafts?.length)return v}catch(e){}const d=sample();return{currentId:d.id,drafts:[d]}}
function current(){return store.drafts.find(d=>d.id===currentId)||store.drafts[0]}
let saveSequence=0;
function persist(){current().updatedAt=Date.now();const sequence=++saveSequence;$('#saveState').textContent='保存中…';renderDraftSelect();window.saveDraftStore(structuredClone(store)).then(()=>{if(sequence===saveSequence)$('#saveState').textContent='已保存'}).catch(()=>{$('#saveState').textContent='保存失败，请备份';toast('浏览器保存失败：请立即备份草稿，检查存储空间或浏览器隐私设置。')})}
function queueSave(){persist()}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),1800)}
function totalComments(d=current()){return d.comments.reduce((n,c)=>n+1+(c.replies?.length||0),0)}
function t(original,translated){return mode==='translated'?(translated||original):original}
function overlayHTML(text,o={}){if(!text||mode!=='overlay')return'';const x=clamp(o.x,0,90),y=clamp(o.y,0,200),w=clamp(o.width||90,20,100),fs=clamp(o.fontSize||15,11,28);return `<span class="translation-overlay" style="left:${x}%;top:${y}%;width:${w}%;font-size:${fs}px">${esc(text)}</span>`}
function renderPreview(){const d=current(),p=d.post,count=totalComments(d);preview.dataset.previewMode=mode;preview.innerHTML=`
  <header class="forum-head"><div class="pann-logo"><b>n</b> 판</div><div class="head-icons"><span>⌕</span><span>♙</span></div></header>
  <nav class="forum-nav"><span>오늘의 판</span><span>톡커들의 선택</span><span>명예의 전당</span><span>☰</span></nav>
  <div class="topic-strip"><span>10대 이야기</span><span>오늘의 톡 ›</span></div>
  <section class="post-head ${p.hot?'with-hot':''}" data-cut-boundary>
    ${p.hot?talkerBadge():''}
    <div class="post-title-wrap editable-preview" data-edit="post-title"><h1 class="post-title original-layer">${esc(p.title)}</h1>${mode==='translated'?`<h1 class="post-title">${esc(p.titleZh||p.title)}</h1>`:overlayHTML(p.titleZh,{x:0,y:4,width:100,fontSize:17})}</div>
    <div class="post-meta editable-preview" data-edit="post-meta">${esc(p.author)} ｜ ${esc(p.time)}<br>조회 ${esc(p.views)} ｜ 추천 <span class="accent" data-score-edit="post" role="button" tabindex="0" aria-label="修改推荐数">${esc(p.likes)}</span></div>
    <div class="post-head-actions"><button class="outline-pill">⇧ 톡 공유하기</button><div class="mini-actions"><span>댓글 <b class="accent">${count}</b></span><span>댓글쓰기</span><span>•••</span></div></div>
  </section>
  <section class="post-body">${p.blocks.map((b,i)=>renderBlock(b,i)).join('')}</section>
  <div class="vote-bar" data-cut-boundary data-score-edit="post" role="button" tabindex="0" aria-label="修改主帖点赞和踩数"><strong class="vote-number vote-up-number">${esc(p.likes)}</strong><div class="vote-circle vote-up">${thumbSvg('up','vote-thumb')}<b>추천</b></div><div class="vote-circle vote-down">${thumbSvg('down','vote-thumb')}<b>반대</b></div><strong class="vote-number vote-down-number">${esc(p.dislikes)}</strong></div>
  <section class="comments-head" data-cut-boundary><h3>댓글 <b>${count}</b></h3><div class="comment-tabs"><b>최신순</b><span>랭킹댓글</span><span>사진댓글</span></div></section>
  <section class="comments">${d.comments.map((c,i)=>renderComment(c,i,false)).join('')}</section>
  <footer class="forum-footer" data-cut-boundary>© NATE Communications · fictional forum mockup</footer>`;
}
function renderBlock(b,i){if(b.type==='image')return `<div class="content-block editable-preview" data-cut-boundary data-edit="block" data-index="${i}"><img class="body-image original-layer" src="${b.src}" alt="上传的正文图片" /></div>`;const shown=t(b.original,b.translation);return `<div class="content-block editable-preview" data-cut-boundary data-edit="block" data-index="${i}"><div class="body-text original-layer">${esc(b.original)}</div>${mode==='translated'?`<div class="body-text">${esc(shown)}</div>`:overlayHTML(b.translation,b.overlay)}</div>`}
function renderComment(c,i,isReply,parentIndex){const shown=t(c.original,c.translation),deleted=c.deleted;return `<article class="comment ${c.hot?'hot ':''}${isReply?'reply':''}" data-cut-boundary data-edit="comment" data-index="${i}" ${isReply?`data-parent="${parentIndex}"`:''}>
 <div class="comment-top"><div class="comment-identity">${c.hot?bestBadge():''}<div class="comment-who"><span class="comment-name">${esc(c.nickname)}</span>${c.author?'<span class="author-tag">작성자</span>':''} ｜ ${esc(c.time)}</div></div><div class="comment-score" data-score-edit="comment" role="button" tabindex="0" aria-label="修改这条评论点赞和踩数"><span class="up">♧ ${esc(c.likes)}</span><span>♧ ${esc(c.dislikes)}</span></div></div>
 <div class="comment-text">${c.replyTo&&!deleted?`<span class="reply-target">@${esc(c.replyTo)}</span>`:''}<span class="original-layer ${deleted?'deleted-text':''}">${esc(deleted?'삭제된 댓글입니다.':c.original)}</span>${mode==='translated'?`<span class="${deleted?'deleted-text':''}">${esc(deleted?'该评论已删除。':shown)}</span>`:overlayHTML(deleted?'该评论已删除。':c.translation,c.overlay)}</div>
 <div class="comment-bottom"><span class="reply-btn">답글 ${c.replies?.length||0}</span> <span class="reply-btn">답글쓰기</span></div></article>${!isReply?(c.replies||[]).map((r,ri)=>renderComment(r,ri,true,i)).join(''):''}`}

function renderDraftSelect(){const s=$('#draftSelect');s.innerHTML=store.drafts.map(d=>`<option value="${d.id}" ${d.id===currentId?'selected':''}>${esc(d.name)}</option>`).join('')}
function field(label,key,value,type='text',extra=''){return `<div class="field"><label for="f_${key}">${label}</label>${type==='textarea'?`<textarea id="f_${key}" data-key="${key}" ${extra}>${esc(value)}</textarea>`:`<input id="f_${key}" data-key="${key}" type="${type}" value="${esc(value)}" ${extra}/>`}</div>`}
function translationFields(obj){const o=obj.overlay||{};return `<div class="section-title"><h3>中文翻译层</h3></div>${field('中文翻译','translation',obj.translation||'', 'textarea','placeholder="留空则不显示翻译层"')}<div class="field-row">${field('水平位置 %','overlay.x',o.x??2,'number','min="0" max="90"')}${field('垂直位置 %','overlay.y',o.y??0,'number','min="0" max="200"')}</div><div class="field-row">${field('宽度 %','overlay.width',o.width??94,'number','min="20" max="100"')}${field('字号 px','overlay.fontSize',o.fontSize??14,'number','min="11" max="28"')}</div>`}
function renderEditor(){const d=current(),box=$('#editorFields');document.querySelectorAll('.editor-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.section===editSection));if(editSection==='settings'){box.innerHTML=`<div class="notice">导出画面固定按 390px 排版，不包含编辑器。图片默认 2 倍清晰度；“自选截图”可手动选择比例与范围。只有完整长图超过安全高度时，才会自动分段以避免空白或截断。</div>${field('导出倍率','settings.scale',d.settings.scale,'number','min="1" max="3" step="1"')}${field('超长图安全分段高度（CSS px）','settings.splitHeight',d.settings.splitHeight,'number','min="600" max="2000"')}`;return}
 if(editSection==='comments'&&active.kind==='post')active={kind:'comment',index:0};
 if(active.kind==='post'){const p=d.post;$('#editorTitle').textContent='主帖';box.innerHTML=`${field('标题','post.title',p.title)}${field('标题中文翻译','post.titleZh',p.titleZh,'textarea','placeholder="留空时纯中文版显示原文"')}<div class="field-row">${field('作者昵称','post.author',p.author)}${field('发布时间','post.time',p.time)}</div><div class="field-row">${field('浏览量','post.views',p.views)}${field('推荐数','post.likes',p.likes,'number')}</div><div class="field-row">${field('踩数','post.dislikes',p.dislikes,'number')}<div class="field"><span class="field-label">徽章</span><label class="check-row"><input data-key="post.hot" type="checkbox" ${p.hot?'checked':''}/> 显示“今日热帖”</label></div></div><div class="section-title"><h3>正文段落与图片</h3><button class="small-btn" data-action="add-block">＋ 添加段落</button></div><label class="upload-label">＋ 上传多张图片<input id="imageUpload" type="file" accept="image/*" multiple></label><div class="item-list">${p.blocks.map((b,i)=>`<div class="item-row"><div class="item-main"><div class="item-name">${b.type==='image'?'图片':esc((b.original||'空段落').slice(0,26))}</div><div class="item-sub">${b.type==='image'?'已嵌入草稿':esc((b.translation||'未填写翻译').slice(0,30))}</div></div><div class="row-actions"><button data-action="edit-block" data-index="${i}">编</button><button data-action="up-block" data-index="${i}">↑</button><button data-action="down-block" data-index="${i}">↓</button><button data-action="delete-block" data-index="${i}">×</button></div></div>`).join('')}</div>`}
 else if(active.kind==='block'){const b=d.post.blocks[active.index];if(!b){active={kind:'post'};return renderEditor()}$('#editorTitle').textContent=b.type==='image'?'正文图片':'正文段落';box.innerHTML=b.type==='image'?`<img src="${b.src}" style="width:100%;display:block;margin-bottom:14px"><p class="subtle">图片已保存在当前草稿中，排序请返回主帖列表操作。</p><div class="editor-actions"><button data-action="back-post">返回主帖</button><button class="danger" data-action="delete-active-block">删除图片</button></div>`:`${field('原文','original',b.original,'textarea')}${translationFields(b)}<div class="editor-actions"><button data-action="back-post">返回主帖</button><button class="danger" data-action="delete-active-block">删除段落</button></div>`}
 else if(active.kind==='comment'){const c=getActiveComment();if(!c){active={kind:'post'};return renderEditor()}$('#editorTitle').textContent=active.parentIndex==null?'评论':'楼中楼回复';box.innerHTML=`${field('昵称','nickname',c.nickname)}${field('时间','time',c.time)}${field('原文','original',c.original,'textarea')}${translationFields(c)}<div class="field-row">${field('点赞数','likes',c.likes,'number')}${field('踩数','dislikes',c.dislikes,'number')}</div>${active.parentIndex!=null?field('回复对象','replyTo',c.replyTo||''):''}<label class="check-row"><input data-key="author" type="checkbox" ${c.author?'checked':''}/> 标记为楼主 <span class="author-tag">작성자</span></label><label class="check-row"><input data-key="hot" type="checkbox" ${c.hot?'checked':''}/> 标记为热评</label><label class="check-row"><input data-key="deleted" type="checkbox" ${c.deleted?'checked':''}/> 显示“该评论已删除”</label><div class="editor-actions"><button data-action="back-comments">返回评论列表</button><button class="danger" data-action="delete-active-comment">删除</button></div>`}
 else if(active.kind==='comments-list'){renderCommentsList(box,d)}
 bindEditorInputs();
}
function renderCommentsList(box,d){$('#editorTitle').textContent='评论列表';box.innerHTML=`<div class="section-title"><h3>全部评论 · ${totalComments(d)}</h3><button class="small-btn" data-action="add-comment">＋ 添加评论</button></div><div class="item-list">${d.comments.map((c,i)=>`<div class="item-row"><div class="item-main"><div class="item-name">${esc(c.nickname)}${c.author?' · 楼主':''}</div><div class="item-sub">${esc(c.original.slice(0,32))} · ${c.replies.length} 条回复</div></div><div class="row-actions"><button data-action="edit-comment" data-index="${i}">编</button><button data-action="add-reply" data-index="${i}">回</button><button data-action="up-comment" data-index="${i}">↑</button><button data-action="down-comment" data-index="${i}">↓</button><button data-action="delete-comment" data-index="${i}">×</button></div></div>${c.replies.map((r,ri)=>`<div class="item-row" style="padding-left:22px"><div class="item-main"><div class="item-name">↳ ${esc(r.nickname)}</div><div class="item-sub">回复 ${esc(r.replyTo||'')} · ${esc(r.original.slice(0,24))}</div></div><div class="row-actions"><button data-action="edit-reply" data-index="${i}" data-reply="${ri}">编</button><button data-action="delete-reply" data-index="${i}" data-reply="${ri}">×</button></div></div>`).join('')}`).join('')}</div>`}
function getActiveComment(){const d=current();return active.parentIndex==null?d.comments[active.index]:d.comments[active.parentIndex]?.replies[active.index]}
function setPath(obj,path,val){const keys=path.split('.');let ref=obj;for(let i=0;i<keys.length-1;i++){ref[keys[i]]??={};ref=ref[keys[i]]}ref[keys.at(-1)]=val}
function activeObjectForKey(key){const d=current();if(key.startsWith('post.'))return d;if(key.startsWith('settings.'))return d;if(active.kind==='block')return d.post.blocks[active.index];if(active.kind==='comment')return getActiveComment();return d}
function bindEditorInputs(){document.querySelectorAll('#editorFields [data-key]').forEach(el=>el.addEventListener(el.type==='checkbox'?'change':'input',()=>{let v=el.type==='checkbox'?el.checked:el.value;if(el.type==='number')v=Number(v);setPath(activeObjectForKey(el.dataset.key),el.dataset.key,v);queueSave();renderPreview()}));const up=$('#imageUpload');if(up)up.addEventListener('change',handleImages)}
async function handleImages(e){const files=[...e.target.files];for(const file of files){if(!file.type.startsWith('image/'))continue;const src=await resizeImage(file,1600,.9);current().post.blocks.push({id:uid('img'),type:'image',src})}queueSave();renderPreview();renderEditor();toast(`已添加 ${files.length} 张图片`)}
function resizeImage(file,max,q){return new Promise((res,rej)=>{const img=new Image(),url=URL.createObjectURL(file);img.onload=()=>{const scale=Math.min(1,max/img.width,max/img.height),c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);URL.revokeObjectURL(url);res(c.toDataURL('image/jpeg',q))};img.onerror=rej;img.src=url})}
function move(arr,i,dir){const j=i+dir;if(j<0||j>=arr.length)return;[arr[i],arr[j]]=[arr[j],arr[i]]}
function newComment(replyTo=''){return{id:uid(replyTo?'r':'c'),nickname:'ㅇㅇ',time:'2026.10.06 01:30',original:'새 댓글을 입력하세요.',translation:'请输入新评论。',likes:0,dislikes:0,author:false,hot:false,deleted:false,replyTo,overlay:{x:2,y:0,width:94,fontSize:14},replies:[]}}
function handleAction(a,el){const d=current(),i=Number(el.dataset.index),r=Number(el.dataset.reply);if(a==='add-block'){d.post.blocks.push({id:uid('b'),type:'text',original:'새 문단을 입력하세요.',translation:'请输入新段落。',overlay:{x:2,y:0,width:94,fontSize:15}});active={kind:'block',index:d.post.blocks.length-1}}
 else if(a==='edit-block')active={kind:'block',index:i};else if(a==='up-block')move(d.post.blocks,i,-1);else if(a==='down-block')move(d.post.blocks,i,1);else if(a==='delete-block')d.post.blocks.splice(i,1);else if(a==='delete-active-block'){d.post.blocks.splice(active.index,1);active={kind:'post'}}else if(a==='back-post')active={kind:'post'};
 else if(a==='add-comment'){d.comments.push(newComment());active={kind:'comment',index:d.comments.length-1}}
 else if(a==='edit-comment')active={kind:'comment',index:i};else if(a==='add-reply'){d.comments[i].replies.push(newComment(d.comments[i].nickname));active={kind:'comment',parentIndex:i,index:d.comments[i].replies.length-1}}
 else if(a==='edit-reply')active={kind:'comment',parentIndex:i,index:r};else if(a==='up-comment')move(d.comments,i,-1);else if(a==='down-comment')move(d.comments,i,1);else if(a==='delete-comment')d.comments.splice(i,1);else if(a==='delete-reply')d.comments[i].replies.splice(r,1);else if(a==='delete-active-comment'){if(active.parentIndex==null)d.comments.splice(active.index,1);else d.comments[active.parentIndex].replies.splice(active.index,1);active={kind:'comments-list'}}else if(a==='back-comments')active={kind:'comments-list'};
 queueSave();renderPreview();renderEditor();
}
$('#editorFields').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b)handleAction(b.dataset.action,b)});
preview.addEventListener('click',e=>{const score=e.target.closest('[data-score-edit]');if(score){openScoreEditor(score);return}const el=e.target.closest('[data-edit]');if(!el)return;if(el.dataset.edit==='post-title'||el.dataset.edit==='post-meta'){active={kind:'post'};editSection='post'}else if(el.dataset.edit==='block'){active={kind:'block',index:Number(el.dataset.index)};editSection='post'}else{active={kind:'comment',index:Number(el.dataset.index),...(el.dataset.parent!=null?{parentIndex:Number(el.dataset.parent)}:{})};editSection='comments'}renderEditor();openMobileEditor()});
let scoreTarget=null;
function openScoreEditor(el){if(el.dataset.scoreEdit==='post')scoreTarget=current().post;else{const row=el.closest('[data-edit="comment"]');scoreTarget=row.dataset.parent==null?current().comments[Number(row.dataset.index)]:current().comments[Number(row.dataset.parent)].replies[Number(row.dataset.index)]}$('#scoreLikes').value=scoreTarget.likes;$('#scoreDislikes').value=scoreTarget.dislikes;$('#scoreDialog').showModal()}
preview.addEventListener('keydown',e=>{const el=e.target.closest('[data-score-edit]');if(el&&['Enter',' '].includes(e.key)){e.preventDefault();openScoreEditor(el)}});
$('#scoreForm').onsubmit=e=>{e.preventDefault();if(!scoreTarget)return;scoreTarget.likes=Math.max(0,Math.floor(Number($('#scoreLikes').value)||0));scoreTarget.dislikes=Math.max(0,Math.floor(Number($('#scoreDislikes').value)||0));persist();renderPreview();renderEditor();$('#scoreDialog').close();scoreTarget=null};
$('#cancelScore').onclick=()=>$('#scoreDialog').close();
$('#editPostScore').onclick=()=>openScoreEditor({dataset:{scoreEdit:'post'}});
function fitScoreDialog(){const viewport=window.visualViewport;document.documentElement.style.setProperty('--score-center',`${(viewport?.offsetTop||0)+(viewport?.height||innerHeight)/2}px`);document.documentElement.style.setProperty('--score-height',`${Math.max(160,(viewport?.height||innerHeight)-24)}px`)}
window.visualViewport?.addEventListener('resize',fitScoreDialog);
window.visualViewport?.addEventListener('scroll',fitScoreDialog);
window.addEventListener('resize',fitScoreDialog);fitScoreDialog();
document.querySelectorAll('.editor-tabs button').forEach(b=>b.addEventListener('click',()=>{editSection=b.dataset.section;active=editSection==='comments'?{kind:'comments-list'}:{kind:'post'};renderEditor()}));
document.querySelectorAll('.segmented button').forEach(b=>b.addEventListener('click',()=>{mode=b.dataset.mode;document.querySelectorAll('.segmented button').forEach(x=>x.classList.toggle('active',x===b));renderPreview()}));
$('#draftSelect').addEventListener('change',e=>{currentId=e.target.value;store.currentId=currentId;active={kind:'post'};persist();renderAll()});
$('#draftMenuBtn').onclick=()=>$('#draftDialog').showModal();
function namePrompt(title,initial=''){const v=prompt(title,initial);return v?.trim()}
$('#newDraftBtn').onclick=()=>{const d=sample();d.id=uid('draft');d.name=namePrompt('新草稿名称','未命名故事')||'未命名故事';store.drafts.push(d);currentId=d.id;store.currentId=currentId;persist();renderAll();$('#draftDialog').close()};
$('#renameDraftBtn').onclick=()=>{const n=namePrompt('重命名草稿',current().name);if(n){current().name=n;persist();renderDraftSelect()}$('#draftDialog').close()};
$('#duplicateDraftBtn').onclick=()=>{const d=structuredClone(current());d.id=uid('draft');d.name+=' · 副本';d.createdAt=d.updatedAt=Date.now();store.drafts.push(d);currentId=d.id;store.currentId=currentId;persist();renderAll();$('#draftDialog').close()};
$('#deleteDraftBtn').onclick=()=>{$('#draftDialog').close();$('#confirmText').textContent=`确定删除“${current().name}”吗？此操作无法撤销。`;$('#confirmDialog').showModal()};
$('#confirmOk').onclick=e=>{e.preventDefault();if(store.drafts.length===1){toast('至少保留一个草稿');$('#confirmDialog').close();return}store.drafts=store.drafts.filter(d=>d.id!==currentId);currentId=store.drafts[0].id;store.currentId=currentId;persist();renderAll();$('#confirmDialog').close()};
$('#exportDraftBtn').onclick=()=>{const blob=new Blob([JSON.stringify({format:'k-forum-draft-v1',draft:current()},null,2)],{type:'application/json'});downloadBlob(blob,safeName(current().name)+'.kforum.json');toast('草稿备份已下载')};
$('#importBtn').onclick=()=>$('#importInput').click();
$('#dialogImportBtn').onclick=()=>{$('#draftDialog').close();$('#importInput').click()};
$('#dialogExportDraftBtn').onclick=()=>{$('#draftDialog').close();$('#exportDraftBtn').click()};
$('#importInput').onchange=async e=>{try{const data=JSON.parse(await e.target.files[0].text()),d=data.draft||data;if(!d.post||!Array.isArray(d.comments))throw Error();d.id=uid('draft');d.name=(d.name||'导入草稿')+' · 导入';store.drafts.push(d);currentId=d.id;store.currentId=currentId;persist();renderAll();toast('草稿已导入')}catch(err){toast('文件格式不正确')}e.target.value=''};
function openMobileEditor(){if(innerWidth<=800)$('#editorPanel').classList.add('open')}
$('#mobileEditBtn').onclick=()=>{$('#editorPanel').classList.add('open')};$('#closeEditorBtn').onclick=()=>$('#editorPanel').classList.remove('open');

function safeName(s){return String(s).replace(/[\\/:*?"<>|]/g,'-').slice(0,60)}
function cssText(){let out='';for(const sheet of [...document.styleSheets]){try{for(const rule of [...sheet.cssRules])out+=rule.cssText+'\n'}catch(e){}}return out}
async function renderSlice(source,start,height,scale){await Promise.all([...source.querySelectorAll('img')].map(img=>img.decode().catch(()=>{})));const canvas=await html2canvas(source,{backgroundColor:'#ffffff',scale,useCORS:true,logging:false,width:390,height:Math.ceil(height),y:Math.round(start),windowWidth:390,scrollX:0,scrollY:0,onclone:doc=>{const page=doc.getElementById(source.id);page.style.width='390px';page.style.maxWidth='none';doc.querySelectorAll('.editable-preview').forEach(x=>x.classList.remove('editable-preview'))}});return await new Promise((res,rej)=>canvas.toBlob(b=>b?res(b):rej(Error('PNG 生成失败')),'image/png',1))}
function loadImage(src){return new Promise((res,rej)=>{const i=new Image();i.onload=()=>res(i);i.onerror=rej;i.src=src})}
function cutRanges(fullHeight,target){const pts=[0,...[...preview.querySelectorAll('[data-cut-boundary]')].map(el=>Math.round(el.offsetTop)),fullHeight].filter((v,i,a)=>v>=0&&a.indexOf(v)===i).sort((a,b)=>a-b);const ranges=[];let start=0;while(start<fullHeight){const ceiling=Math.min(fullHeight,start+target);let end=pts.filter(p=>p>start+240&&p<=ceiling).at(-1)||ceiling;if(fullHeight-end<180)end=fullHeight;ranges.push([start,end-start]);start=end}return ranges}
async function exportImages(split=false){const d=current(),scale=clamp(d.settings.scale,1,3)||2;document.body.classList.add('is-exporting');$('#exportFullBtn').disabled=$('#exportSplitBtn').disabled=true;toast('正在生成图片…');await document.fonts.ready;await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));const h=Math.ceil(preview.scrollHeight);let ranges;if(split)ranges=cutRanges(h,clamp(d.settings.splitHeight,600,2000)||1160);else if(h*scale>28000){ranges=cutRanges(h,12000/scale);toast(`内容很长，将安全导出为 ${ranges.length} 张`)}else ranges=[[0,h]];try{const blobs=[];for(let i=0;i<ranges.length;i++)blobs.push(await renderSlice(preview,ranges[i][0],ranges[i][1],scale));showExports(blobs,split||ranges.length>1)}catch(e){console.error(e);toast('导出失败，请减少超大图片后重试')}finally{document.body.classList.remove('is-exporting');$('#exportFullBtn').disabled=$('#exportSplitBtn').disabled=false}}
function showExports(blobs,isParts,message=''){exportUrls.forEach(URL.revokeObjectURL);exportUrls=blobs.map(URL.createObjectURL);const name=safeName(current().name);$('#exportDialogTitle').textContent=isParts?`${blobs.length} 张分图`:'完整长图';$('#exportMessage').textContent=message||(isParts?'已生成分图。手机上可长按图片保存，也可点下方按钮下载。':'导出尺寸为 780px 宽（2倍设置时）。手机上可长按图片保存。');$('#exportGallery').innerHTML=exportUrls.map((u,i)=>`<div class="export-item"><img src="${u}" alt="导出图片 ${i+1}"><a href="${u}" download="${name}${blobs.length>1?'-'+String(i+1).padStart(2,'0'):''}.png">下载${blobs.length>1?'第 '+(i+1)+' 张':' PNG'}</a></div>`).join('');$('#exportDialog').showModal()}
function downloadBlob(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function cropDisplayScale(){return $('#cropPreviewImage').clientWidth/390||1}
function updateCropUI(scroll=false){const h=Math.min(manualCrop.height,manualCrop.fullHeight||manualCrop.height),max=Math.max(0,manualCrop.fullHeight-h);manualCrop.height=h;manualCrop.start=clamp(manualCrop.start,0,max);const scale=cropDisplayScale(),sel=$('#cropSelection'),pos=$('#cropPosition');sel.style.top=`${manualCrop.start*scale}px`;sel.style.height=`${h*scale}px`;pos.max=max;pos.value=manualCrop.start;$('#cropPositionValue').textContent=`${Math.round(manualCrop.start)}px`;$('#cropHeight').value=h;$('#cropHeightValue').textContent=`${Math.round(h)}px`;$('#cropPreviewWrap').style.height=`${manualCrop.fullHeight*scale}px`;$('#cropQueue').innerHTML=manualCrop.ranges.length?`<b>已选 ${manualCrop.ranges.length} 张：</b> ${manualCrop.ranges.map((r,i)=>`第${i+1}张 ${Math.round(r[0])}–${Math.round(r[0]+r[1])}px`).join(' · ')}`:'尚未加入截图';$('#generateCropImages').disabled=!manualCrop.ranges.length;$('#generateCropImages').textContent=manualCrop.ranges.length?`生成 ${manualCrop.ranges.length} 张图片`:'生成已选图片';if(scroll){const viewport=$('#cropViewport'),top=manualCrop.start*scale;viewport.scrollTo({top:Math.max(0,top-35),behavior:'smooth'})}}
function setCropRatio(value){document.querySelectorAll('.crop-ratios button').forEach(b=>b.classList.toggle('active',b.dataset.ratio===value));const custom=value==='free';manualCrop.ratio=custom?null:Number(value);$('.crop-height-row').classList.toggle('is-locked',!custom);$('#cropHeight').disabled=!custom;if(!custom)manualCrop.height=Math.round(390/manualCrop.ratio);updateCropUI(true)}
async function openManualCrop(){const btn=$('#exportSplitBtn');btn.disabled=true;toast('正在准备整页预览…');document.body.classList.add('is-exporting');await document.fonts.ready;await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));try{const canvas=await html2canvas(preview,{backgroundColor:'#fff',scale:1,useCORS:true,logging:false,width:390,windowWidth:390,scrollX:0,scrollY:0,onclone:doc=>doc.querySelectorAll('.editable-preview').forEach(x=>x.classList.remove('editable-preview'))});manualCrop={start:0,height:520,ratio:.75,fullHeight:Math.ceil(preview.scrollHeight),ranges:[],drag:null};const img=$('#cropPreviewImage');img.onload=()=>{setCropRatio('0.75');updateCropUI();$('#manualCropDialog').showModal()};img.src=canvas.toDataURL('image/jpeg',.88)}catch(e){console.error(e);toast('预览生成失败，请减少超大图片后重试')}finally{document.body.classList.remove('is-exporting');btn.disabled=false}}
document.querySelectorAll('.crop-ratios button').forEach(b=>b.onclick=()=>setCropRatio(b.dataset.ratio));
$('#cropHeight').oninput=e=>{manualCrop.height=Number(e.target.value);updateCropUI()};
$('#cropPosition').oninput=e=>{manualCrop.start=Number(e.target.value);updateCropUI(true)};
$('#cropPrevBtn').onclick=()=>{manualCrop.start-=manualCrop.height;updateCropUI(true)};
$('#cropNextBtn').onclick=()=>{manualCrop.start+=manualCrop.height;updateCropUI(true)};
$('#addCropRange').onclick=()=>{manualCrop.ranges.push([Math.round(manualCrop.start),Math.round(manualCrop.height)]);manualCrop.start+=manualCrop.height;updateCropUI(true)};
$('#clearCropQueue').onclick=()=>{manualCrop.ranges=[];updateCropUI()};
$('#generateCropImages').onclick=async()=>{const ranges=[...manualCrop.ranges],scale=clamp(current().settings.scale,1,3)||2;$('#manualCropDialog').close();$('#exportFullBtn').disabled=$('#exportSplitBtn').disabled=true;document.body.classList.add('is-exporting');toast(`正在生成 ${ranges.length} 张图片…`);try{const blobs=[];for(const r of ranges)blobs.push(await renderSlice(preview,r[0],r[1],scale));showExports(blobs,true,'已按你选择的比例和位置生成。手机上可长按图片保存。')}catch(e){console.error(e);toast('导出失败，请减少选区数量后重试')}finally{document.body.classList.remove('is-exporting');$('#exportFullBtn').disabled=$('#exportSplitBtn').disabled=false}};
$('#cropSelection').addEventListener('pointerdown',e=>{manualCrop.drag={y:e.clientY,start:manualCrop.start};e.currentTarget.setPointerCapture(e.pointerId)});
$('#cropSelection').addEventListener('pointermove',e=>{if(!manualCrop.drag)return;manualCrop.start=manualCrop.drag.start+(e.clientY-manualCrop.drag.y)/cropDisplayScale();updateCropUI()});
$('#cropSelection').addEventListener('pointerup',e=>{manualCrop.drag=null;e.currentTarget.releasePointerCapture(e.pointerId)});
$('#cropSelection').addEventListener('keydown',e=>{if(!['ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();manualCrop.start+=e.key==='ArrowUp'?-10:10;updateCropUI(true)});
$('#closeManualCrop').onclick=()=>$('#manualCropDialog').close();
$('#exportFullBtn').onclick=()=>exportImages(false);$('#exportSplitBtn').onclick=openManualCrop;$('#closeExportDialog').onclick=()=>$('#exportDialog').close();
function renderAll(){renderDraftSelect();renderPreview();renderEditor()}
renderAll();persist();

function registerWebMCP(){const mc=document.modelContext;if(!mc?.registerTool)return;const register=tool=>{try{void Promise.resolve(mc.registerTool(tool)).catch(()=>{})}catch(e){}}
 register({name:'update_forum_post',title:'更新论坛主帖',description:'更新当前草稿的主帖标题、标题中文翻译、作者或正文双语段落。',inputSchema:{type:'object',properties:{title:{type:'string'},titleZh:{type:'string'},author:{type:'string'},blocks:{type:'array',items:{type:'object',properties:{original:{type:'string'},translation:{type:'string'}},required:['original'],additionalProperties:false}}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||!Object.keys(input).length)throw Error('至少提供一个要更新的字段');const p=current().post;for(const k of ['title','titleZh','author'])if(k in input){if(typeof input[k]!=='string')throw Error(k+' 必须是字符串');p[k]=input[k]}if('blocks'in input){if(!Array.isArray(input.blocks))throw Error('blocks 必须是数组');p.blocks=input.blocks.map(b=>{if(!b||typeof b.original!=='string')throw Error('每个段落必须包含 original');return{id:uid('b'),type:'text',original:b.original,translation:typeof b.translation==='string'?b.translation:'',overlay:{x:2,y:0,width:94,fontSize:15}}})}persist();renderAll();return{draftId:current().id,blockCount:p.blocks.length}}});
 register({name:'add_forum_comment',title:'添加论坛评论',description:'向当前草稿添加一条顶层评论，或按父评论 ID 添加楼中楼回复。',inputSchema:{type:'object',properties:{nickname:{type:'string'},original:{type:'string'},translation:{type:'string'},parentCommentId:{type:'string'},replyTo:{type:'string'}},required:['nickname','original'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.nickname!=='string'||typeof input.original!=='string')throw Error('nickname 和 original 为必填字符串');const c=newComment(input.replyTo||'');c.nickname=input.nickname;c.original=input.original;c.translation=typeof input.translation==='string'?input.translation:'';if(input.parentCommentId){const parent=current().comments.find(x=>x.id===input.parentCommentId);if(!parent)throw Error('找不到指定父评论');parent.replies.push(c)}else current().comments.push(c);persist();renderAll();return{commentId:c.id,totalComments:totalComments()}}})}
registerWebMCP();
